window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-56f95dc2beca6c02"]={"versions": [{"id": "FIG-56f95dc2beca6c02", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Konfigurationsstruktur (ECU Configuration Parameter Definition, ECUC) des AUTOSAR Crypto Service Managers (CSM). Es spezifiziert die Container-Hierarchie des übergeordneten Konfigurationscontainers <code>CsmPrimitives</code> und dessen zulässige Sub-Container für kryptografische Primitiven und Schlüsselmanagement-Operationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine hierarchische Kompositionsstruktur basierend auf der Metaklasse <code>EcucParamConfContainerDef</code>:</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordneter Container:</strong></li>\n<li><code>CsmPrimitives</code> (Multiplizität: <code>0..*</code>)</li>\n<li><strong>Untergeordnete Sub-Container (<code>+subContainer</code>), jeweils mit Multiplizität <code>0..1</code>:</strong></li>\n<li>Kryptografische Algorithmen & Primitiven:</li>\n<li><code>CsmHash</code></li>\n<li><code>CsmMacGenerate</code></li>\n<li><code>CsmMacVerify</code></li>\n<li><code>CsmEncrypt</code></li>\n<li><code>CsmDecrypt</code></li>\n<li><code>CsmAEADEncrypt</code></li>\n<li><code>CsmAEADDecrypt</code></li>\n<li><code>CsmSignatureGenerate</code></li>\n<li><code>CsmSignatureVerify</code></li>\n<li><code>CsmRandomGenerate</code></li>\n<li>Schlüsselmanagement- und Zustandsoperationen:</li>\n<li><code>CsmJobKeySetValid</code></li>\n<li><code>CsmJobKeySetInvalid</code></li>\n<li><code>CsmJobRandomSeed</code></li>\n<li><code>CsmJobKeyDerive</code></li>\n<li><code>CsmJobKeyGenerate</code></li>\n<li><code>CsmJobKeyExchangeCalcPubVal</code></li>\n<li><code>CsmJobKeyExchangeCalcSecret</code></li>\n</ul>\n<p class=\"fig-p\">Alle Sub-Container sind über Kompositionsbeziehungen (<code>+subContainer</code>, ausgefüllte Raute an <code>CsmPrimitives</code>) an den Elterncontainer angebunden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keine Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge dar. Es definiert die statische Schachtelung für den ECUC-Generierungsprozess und die Parametrierung der kryptografischen Primitiven vor der Kompilierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativ für die Konfigurationsstruktur des CSM im BSW-Stack. Innerhalb einer <code>CsmPrimitives</code>-Instanz dürfen die 17 definierten Sub-Container optional jeweils maximal einmal konfiguriert werden (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Die Konfigurationstools müssen sicherstellen, dass nur spezifizierte Primitiv-Container unterhalb von <code>CsmPrimitives</code> instanziiert werden.</p>"}, {"id": "FIG-0f5de4b9e6eb17ad", "releases": ["R22-11", "EXTERN"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Metamodell-Ausschnitt zur Konfigurationsstruktur (ECU Configuration Parameter Definition, ECUC) des AUTOSAR Crypto Service Managers (CSM). Es spezifiziert die Container-Hierarchie des übergeordneten Konfigurationscontainers <code>CsmPrimitives</code> und dessen zulässige Sub-Container für kryptografische Primitiven und Schlüsselmanagement-Operationen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine hierarchische Kompositionsstruktur basierend auf der Metaklasse <code>EcucParamConfContainerDef</code>:</p>\n<ul class=\"fig-list\">\n<li><strong>Übergeordneter Container:</strong></li>\n<li><code>CsmPrimitives</code> (Multiplizität: <code>0..*</code>)</li>\n<li><strong>Untergeordnete Sub-Container (<code>+subContainer</code>), jeweils mit Multiplizität <code>0..1</code>:</strong></li>\n<li>Kryptografische Algorithmen & Primitiven:</li>\n<li><code>CsmHash</code></li>\n<li><code>CsmMacGenerate</code></li>\n<li><code>CsmMacVerify</code></li>\n<li><code>CsmEncrypt</code></li>\n<li><code>CsmDecrypt</code></li>\n<li><code>CsmAEADEncrypt</code></li>\n<li><code>CsmAEADDecrypt</code></li>\n<li><code>CsmSignatureGenerate</code></li>\n<li><code>CsmSignatureVerify</code></li>\n<li><code>CsmRandomGenerate</code></li>\n<li><code>CsmCustom</code></li>\n<li>Schlüsselmanagement- und Zustandsoperationen:</li>\n<li><code>CsmJobKeySetValid</code></li>\n<li><code>CsmJobKeySetInvalid</code></li>\n<li><code>CsmJobRandomSeed</code></li>\n<li><code>CsmJobKeyDerive</code></li>\n<li><code>CsmJobKeyGenerate</code></li>\n<li><code>CsmJobKeyExchangeCalcPubVal</code></li>\n<li><code>CsmJobKeyExchangeCalcSecret</code></li>\n</ul>\n<p class=\"fig-p\">Alle Sub-Container sind über Kompositionsbeziehungen (<code>+subContainer</code>, ausgefüllte Raute an <code>CsmPrimitives</code>) an den Elterncontainer angebunden.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Konfigurationsmetamodell stellt das Diagramm keine Laufzeitabläufe, Nachrichtenflüsse oder Zustandsübergänge dar. Es definiert die statische Schachtelung für den ECUC-Generierungsprozess und die Parametrierung der kryptografischen Primitiven vor der Kompilierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm ist normativ für die Konfigurationsstruktur des CSM im BSW-Stack. Innerhalb einer <code>CsmPrimitives</code>-Instanz dürfen die 18 definierten Sub-Container optional jeweils maximal einmal konfiguriert werden (<code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>). Die Konfigurationstools müssen sicherstellen, dass nur spezifizierte Primitiv-Container unterhalb von <code>CsmPrimitives</code> instanziiert werden.</p>"}], "trans": [{"from": "FIG-56f95dc2beca6c02", "to": "FIG-0f5de4b9e6eb17ad", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neuer Kind-Container <code>CsmCustom: EcucParamConfContainerDef</code> über Komposition <code>+subContainer</code> an <code>CsmPrimitives</code> angebunden mit Kardinalität <code>lowerMultiplicity = 0</code>, <code>upperMultiplicity = 1</code>.</li>\n</ul>"}]};
